class InertServer extends EventEmitter {
  listen(...args) {
    const callback = args.find(value => typeof value === 'function');
    if (callback) process.nextTick(callback);
    return this;
  }
}

function loadService(name, rootServer) {
  const filename = serviceFilenames[name];
  const embeddedPage = name === 'chat' ? prepareChatPage(CHAT_HTML) : name === 'board' ? BOARD_HTML : null;
  const source = (embeddedPage ? `const __SERVICE_PAGE = ${JSON.stringify(embeddedPage)};\n` : '') +
    prepareServiceSource(name, serviceSources[name]) +
    (name === 'download'
      ? '\nmodule.exports = { app, server };\n'
      : '\nmodule.exports = { app, server };\n');
  const serviceRequire = Module.createRequire(filename);
  const moduleObject = { exports: {} };
  const inertServer = new InertServer();
  const useRootServer = name === 'chat';

  function localRequire(request) {
    if (request === 'http' || request === 'https') {
      const nativeModule = serviceRequire(request);
      const replacement = Object.create(nativeModule);
      replacement.createServer = (...args) => useRootServer
        ? rootServer
        : inertServer;
      return replacement;
    }
    return serviceRequire(request);
  }

  const compiled = vm.runInThisContext(Module.wrap(source), { filename });
  const run = () => compiled(
    moduleObject.exports,
    localRequire,
    moduleObject,
    filename,
    path.dirname(filename)
  );

  // The chat service attaches Socket.IO to the shared HTTPS server.  Its
  // legacy startup call must not bind that server before all routes are set.
  const originalListen = rootServer.listen;
  if (useRootServer) rootServer.listen = () => rootServer;
  try {
    run();
  } finally {
    if (useRootServer) rootServer.listen = originalListen;
  }

  return moduleObject.exports;
}

const rootApp = express();
rootApp.get('/', (req, res) => res.sendFile(path.join(APP_DIR, 'index.html')));
rootApp.get('/index.html', (req, res) => res.sendFile(path.join(APP_DIR, 'index.html')));
rootApp.get('/__test/status', (req, res) => {
  res.json({
    process: process.pid,
    port: PORT,
    services: ['navigation', 'chat', 'board', 'download'],
    websocket: true
  });
});

const pfxPath = path.join(CERT_DIR, 'server.pfx');
const keyPath = path.join(CERT_DIR, 'server.key');
const certPath = path.join(CERT_DIR, 'server.crt');
let protocol = 'http';
let rootServer;

if (!process.env.WEBSERVE_HTTP && fs.existsSync(pfxPath)) {
  rootServer = https.createServer({
    pfx: fs.readFileSync(pfxPath),
    passphrase: '123456'
  }, rootApp);
  protocol = 'https';
} else if (!process.env.WEBSERVE_HTTP && fs.existsSync(keyPath) && fs.existsSync(certPath)) {
  rootServer = https.createServer({
    key: fs.readFileSync(keyPath),
    cert: fs.readFileSync(certPath)
  }, rootApp);
  protocol = 'https';
} else {
  rootServer = http.createServer(rootApp);
}

const navigation = loadService('navigation', rootServer);
const chat = loadService('chat', rootServer);
const board = loadService('board', rootServer);
const download = loadService('download', rootServer);

function dispatchWithPath(service, pathPrefix) {
  return (req, res, next) => {
    const suffix = req.url === '/' ? '' : req.url;
    req.url = pathPrefix + suffix;
    service(req, res, next);
  };
}

// Service pages use stable, clickable paths instead of their former ports.
rootApp.get('/chat', (req, res, next) => {
  if (req.path === '/chat') return res.redirect('/chat/');
  next();
});
rootApp.get('/board', (req, res, next) => {
  if (req.path === '/board') return res.redirect('/board/');
  next();
});
rootApp.get('/download', (req, res, next) => {
  if (req.path === '/download') return res.redirect('/download/');
  next();
});
rootApp.get('/chat/', (req, res) => {
  res.type('html').send(prepareChatPage(CHAT_HTML));
});
rootApp.get('/board/', (req, res) => {
  res.type('html').send(BOARD_HTML);
});
rootApp.use('/chat', chat.app);
// The chat page is embedded but still expects its PWA manifest at the root.
rootApp.use('/manifest.json', dispatchWithPath(chat.app, '/manifest.json'));
rootApp.use('/board', board.app);
rootApp.use('/download', download.app);

// Explicit API aliases avoid collisions between the navigation, chat, board,
// and resource-manager APIs while retaining their original API paths.
rootApp.use('/chat-api', dispatchWithPath(chat.app, '/api'));
rootApp.use('/chat-upload', dispatchWithPath(chat.app, '/upload'));
rootApp.use('/upload', dispatchWithPath(chat.app, '/upload'));
for (const route of ['/api/update-profile', '/api/register', '/api/me', '/api/logout']) {
  rootApp.use(route, dispatchWithPath(chat.app, route));
}
rootApp.use('/board-api', dispatchWithPath(board.app, '/api'));
rootApp.use('/download-api', dispatchWithPath(download.app, '/api'));

for (const route of ['/api/auth', '/api/admin', '/api/file', '/api/folder', '/api/ftps/config']) {
  rootApp.use(route, dispatchWithPath(download.app, route));
}
for (const route of ['/files', '/shared']) {
  rootApp.use(route, dispatchWithPath(download.app, route));
}

rootApp.use('/resource', express.static(path.join(FILES_DIR, 'resources')));
rootApp.use('/uploads', express.static(path.join(FILES_DIR, 'uploads')));
rootApp.use(navigation.app);

rootServer.on('clientError', (error, socket) => {
  if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
  else socket.destroy();
});

rootServer.listen(PORT, '::', () => {
  console.log(`Webserve running at ${protocol}://localhost:${PORT}`);
  console.log('Services: /, /chat, /board, /download');
});

function shutdown() {
  rootServer.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 5000).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);